class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_end = True

    def search_prefix(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        # DFS to collect all words
        results = []
        self._dfs(node, prefix, results)
        return results

    def _dfs(self, node, path, results):
        if node.is_end:
            results.append(path)
        for ch, child in node.children.items():
            self._dfs(child, path + ch, results)
`

**Complexity:** Insert: $O(L)$ per word (L = word length). Prefix search: $O(P + K)$ where $P$ is prefix length and $K$ is total length of all matching words. Space: $O(\sum L_i)$ total characters stored.

**Approach:** Use two stacks to implement a queue, each augmented with running max.

**Solution:** Build a max-queue using two max-stacks:

`python
class MaxStack:
    def __init__(self):
        self.stack = []
        self.max_stack = []
    def push(self, val):
        self.stack.append(val)
        m = max(val, self.max_stack[-1] if self.max_stack else val)
        self.max_stack.append(m)
    def pop(self):
        self.max_stack.pop()
        return self.stack.pop()
    def get_max(self):
        return self.max_stack[-1] if self.max_stack else float('-inf')
    def is_empty(self):
        return len(self.stack) == 0

class MaxQueue:
    def __init__(self):
        self.in_stack = MaxStack()   # for enqueue
        self.out_stack = MaxStack()  # for dequeue
    def enqueue(self, val):
        self.in_stack.push(val)
    def dequeue(self):
        if self.out_stack.is_empty():
            while not self.in_stack.is_empty():
                self.out_stack.push(self.in_stack.pop())
        return self.out_stack.pop()
    def get_max(self):
        return max(self.in_stack.get_max(),
                   self.out_stack.get_max())
`

All operations are $O(1)$ amortized. Each element is pushed/popped at most twice total (once per stack).

