// Naive recursive â€” O(2^n) time
int fib(int n) {
    if (n <= 0) return 0;
    if (n == 1) return 1;
    return fib(n-1) + fib(n-2);
}

// Memoized â€” O(n) time, O(n) space
int memo[1000] = {0};
int fib_memo(int n) {
    if (n <= 0) return 0;
    if (n == 1) return 1;
    if (memo[n]) return memo[n];
    return memo[n] = fib_memo(n-1) + fib_memo(n-2);
}

// Iterative â€” O(n) time, O(1) space
int fib_iter(int n) {
    int a=0, b=1;
    for (int i=2; i<=n; i++) { int t=a+b; a=b; b=t; }
    return b;
}
```

Naive recursion is $O(2^n)$ due to overlapping subproblems. Memoization or iteration achieves $O(n)$. The iterative version uses $O(1)$ space since we only need the last two values.
